INSERT INTO `property` VALUES (2,8,'Tamba\'s palace','Where heroes born','Tissamaharama',NULL,NULL,NULL,NULL,1500.00,0.00,0.00,2,1,1,NULL,NULL,0,1,NULL,5.00,'verification cancelled','property_1783070893932_gkvmt7mvg.jpeg',1,'requested','bungalow',NULL,NULL),(5,8,'Cozy Apartment near Galle Face','Comfortable 2-bedroom apartment just 5 minutes walk from the iconic Galle Face Green. Enjoy sea breezes from the balcony and explore the best of Colombo\'s dining and nightlife scene.','18 Galle Road, Colombo 03, Sri Lanka',NULL,NULL,NULL,NULL,7200.00,0.00,0.00,3,2,1,NULL,NULL,1,1,NULL,4.91,NULL,'https://images.unsplash.com/photo-1522708323590-d24dbb6b0267?w=800&auto=format&fit=crop',0,'approved','apartment',6.91950000,79.84660000),(6,8,'Heritage Villa inside Galle Fort','Step back in time in this beautifully restored 200-year-old Dutch colonial villa inside the UNESCO World Heritage Galle Fort. Original tile floors, wooden beam ceilings, and private courtyard garden.','Church Street, Galle Fort, Galle, Sri Lanka',NULL,NULL,NULL,NULL,22000.00,0.00,0.00,6,4,1,NULL,NULL,1,1,NULL,3.60,NULL,'https://images.unsplash.com/photo-1613490493576-7fde63acd811?w=800&auto=format&fit=crop',1,'approved','villa',6.02640000,80.21700000),(7,8,'Beachfront Bungalow in Unawatuna','Wake up to the sound of waves at this charming beachfront bungalow in Unawatuna. Private beach access, hammock terrace, outdoor shower, and stunning sunset views over the Indian Ocean.','Unawatuna Beach, Galle, Sri Lanka',NULL,NULL,NULL,NULL,9500.00,0.00,0.00,4,2,1,NULL,NULL,1,1,NULL,3.77,NULL,'https://images.unsplash.com/photo-1510798831971-661eb04b3739?w=800&auto=format&fit=crop',0,'approved','bungalow',6.01390000,80.24930000),(8,8,'Mirissa Surf Shack & Studio','Chilled-out studio a 2-minute stroll from Mirissa Beach. Ideal for surfers and backpackers. Surfboard storage, outdoor area for drying, bike hire available. Close to whale-watching boats.','Mirissa Beach Road, Mirissa, Sri Lanka',NULL,NULL,NULL,NULL,3200.00,0.00,0.00,2,1,1,NULL,NULL,0,1,NULL,4.03,NULL,'https://images.unsplash.com/photo-1631049307264-da0ec9d70304?w=800&auto=format&fit=crop',1,'requested','room',5.94810000,80.45430000),(9,8,'Colonial Tea Estate House — Kandy Hills','Romantic colonial-era house set in a working tea estate with breathtaking views of misty mountains. Features a wrap-around veranda, wood-burning fireplace, and butler service. Ideal for couples.','Hantana Road, Kandy, Sri Lanka',NULL,NULL,NULL,NULL,15000.00,0.00,0.00,4,3,1,NULL,NULL,1,1,NULL,4.35,NULL,'https://images.unsplash.com/photo-1568605114967-8130f3a36994?w=800&auto=format&fit=crop',0,'approved','house',7.29060000,80.63370000),(10,8,'Boutique Room with Lake View','Comfortable private room in a guesthouse overlooking the scenic Kandy Lake. Short walk to the Temple of the Tooth Relic. Breakfast included, homely atmosphere, perfect for solo travellers.','Sangaraja Mawatha, Kandy, Sri Lanka',NULL,NULL,NULL,NULL,3800.00,0.00,0.00,2,1,1,NULL,NULL,0,1,NULL,4.44,NULL,'https://images.unsplash.com/photo-1631049307264-da0ec9d70304?w=800&auto=format&fit=crop',1,'requested','room',7.29260000,80.64130000),(11,8,'Ella Mountain Cabin Retreat','Remote off-grid cabin perched at 1,500m with unobstructed views of Ella Rock and the Little Adam\'s Peak. Solar power, rainwater harvesting, organic garden. A true escape from city life.','Ella Village, Badulla District, Sri Lanka',NULL,NULL,NULL,NULL,6500.00,0.00,0.00,3,1,1,NULL,NULL,1,1,NULL,4.88,NULL,'https://images.unsplash.com/photo-1449158743715-0a90ebb6d2d8?w=800&auto=format&fit=crop',0,'approved','cabin',6.86670000,81.04660000),(12,8,'Airport Transit Apartment — Negombo','Stress-free transit accommodation just 10 minutes from Bandaranaike International Airport. Free airport transfers, late check-out, blackout curtains, and luggage storage. 24/7 reception.','Lewis Place, Negombo, Sri Lanka',NULL,NULL,NULL,NULL,5500.00,0.00,0.00,3,2,1,NULL,NULL,0,1,NULL,3.89,NULL,'https://images.unsplash.com/photo-1522708323590-d24dbb6b0267?w=800&auto=format&fit=crop',1,'inspecting','apartment',7.20940000,79.84030000),(13,8,'Negombo Beach House','Family-friendly 4-bedroom beach house with a private pool and barbecue area on Negombo Beach. Spacious living areas, full kitchen, bike rentals, and easy access to the famous Negombo fish market.','Poruthota Road, Negombo, Sri Lanka',NULL,NULL,NULL,NULL,12500.00,0.00,0.00,8,4,1,NULL,NULL,1,1,NULL,4.42,NULL,'https://images.unsplash.com/photo-1568605114967-8130f3a36994?w=800&auto=format&fit=crop',0,'approved','house',7.21130000,79.83240000),(14,8,'Eco-Lodge near Sigiriya Rock','Immersive eco-lodge surrounded by jungle with views of the iconic Sigiriya Rock Fortress. Open-air bathrooms, nature walks, birdwatching tours, and evening campfires. UNESCO World Heritage Site steps away.','Sigiriya Village, Matale District, Sri Lanka',NULL,NULL,NULL,NULL,8800.00,0.00,0.00,2,1,1,NULL,NULL,1,1,NULL,4.83,NULL,'https://images.unsplash.com/photo-1510798831971-661eb04b3739?w=800&auto=format&fit=crop',1,'approved','bungalow',7.95680000,80.76030000),(15,8,'Nilaveli Beach Villa','Stunning beachfront villa on the pristine shores of Nilaveli — one of Sri Lanka\'s most beautiful beaches. Private beach, infinity pool, outdoor dining pavilion. Close to Pigeon Island Nationa','Nilaveli Beach, Trincomalee, Sri Lanka',NULL,NULL,NULL,NULL,25000.00,0.00,0.00,8,4,1,NULL,NULL,1,1,NULL,NULL,NULL,'https://images.unsplash.com/photo-1613490493576-7fde63acd811?w=800&auto=format&fit=crop',0,'approved','villa',8.71080000,81.19780000),(16,8,'Yasiru\'s home','Apartment, Home at Matara','Matara',NULL,NULL,NULL,NULL,4000.00,0.00,0.00,2,1,1,NULL,NULL,0,1,NULL,NULL,NULL,'property_1783509797473_gum6jqp9w.jpg',0,'none','apartment',NULL,NULL);
